import{_ as t,a as o,b as i,c as e,d as s}from"./chunks/device-tablet-landscape.D4FvTdpl.js";import{_ as r,o as p,c,a2 as n}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"不同设备上的样子","description":"同一个应用，几种身形。KomaYomi 靠重排来适应屏幕，而不是另做一套手机版把功能藏起来——按钮该在的都在，只是会换个位置。这一页说明主界面在各尺寸下怎么排，每种尺寸都配了真实截图。","frontmatter":{"description":"同一个应用，几种身形。KomaYomi 靠重排来适应屏幕，而不是另做一套手机版把功能藏起来——按钮该在的都在，只是会换个位置。这一页说明主界面在各尺寸下怎么排，每种尺寸都配了真实截图。"},"headers":[],"relativePath":"zh/guide/devices.md","filePath":"zh/guide/devices.md","lastUpdated":1794794587000}'),l={name:"zh/guide/devices.md"};function d(m,a,g,h,f,u){return p(),c("div",null,[...a[0]||(a[0]=[n('<h1 id="不同设备上的样子" tabindex="-1">不同设备上的样子 <a class="header-anchor" href="#不同设备上的样子" aria-label="Permalink to &quot;不同设备上的样子&quot;">​</a></h1><p>同一个应用，几种身形。KomaYomi 靠重排来适应屏幕，而不是另做一套手机版把功能藏起来——按钮该在的都在，只是会换个位置。这一页说明主界面在各尺寸下怎么排，每种尺寸都配了真实截图。</p><h2 id="pc-横屏-—-1440-px" tabindex="-1">PC 横屏 — 1440 px <a class="header-anchor" href="#pc-横屏-—-1440-px" aria-label="Permalink to &quot;PC 横屏 — 1440 px&quot;">​</a></h2><figure class="shot"><img src="'+t+'" alt="1440 px 宽的窗口：左侧图库侧栏、中间三栏对照、右侧笔记栏"><figcaption>1440 px：左边侧栏，中间三语并排，右边笔记栏。</figcaption></figure><p>1440 px 时侧栏（约 270 px）、对照舞台和笔记栏能同时显示。三语并排铺开，一段对话不用滚动就能看全；窗口在启动时宽于 1180 px，笔记栏默认展开——拖动分隔条可以加宽，按 <strong>笔记</strong>（<code>N</code>）可以收起。</p><h2 id="pc-竖屏-—-900-×-1200" tabindex="-1">PC 竖屏 — 900 × 1200 <a class="header-anchor" href="#pc-竖屏-—-900-×-1200" aria-label="Permalink to &quot;PC 竖屏 — 900 × 1200&quot;">​</a></h2><figure class="shot"><img src="'+o+'" alt="900 × 1200 的窄窗口：图库收成抽屉，对照栏纵向堆叠"><figcaption>900 × 1200：侧栏收进抽屉，对照只剩一栏，笔记栏默认收起。</figcaption></figure><p>到 900 px 就进入窄屏模式：图库收进 ☰ 按钮后面的抽屉，对照视图变成单栏纵向堆叠，笔记栏默认关闭——按 <strong>笔记</strong> 再叫出来。工具栏分组会去掉文字标签，放不下的操作挪进 <strong>More</strong>。</p><h2 id="手机竖屏-—-390-×-844" tabindex="-1">手机竖屏 — 390 × 844 <a class="header-anchor" href="#手机竖屏-—-390-×-844" aria-label="Permalink to &quot;手机竖屏 — 390 × 844&quot;">​</a></h2><figure class="shot"><img src="'+i+'" alt="390 × 844 的窗口：顶栏与工具栏折成多行"><figcaption>390 × 844：顶栏折成三行，工具栏再折几行；触屏布局一次只显示一条语言栏。</figcaption></figure><p>390 px 的触屏手机上，顶栏折成三行：先是导航和翻页，再是界面语言与导出，最后是 <strong>Panels / Compare</strong> 视图切换。对照区一次只显示一条语言栏：舞台上方的语言标签栏（JA / EN / ZH）决定当前看哪一种已启用的语言；启用两种以上语言时，也可以左右滑动切换，标签栏右侧会给出提示。工具栏里的语言开关决定先启用哪些语言。工具栏分组会折到下一行，而不是横向滚走；图库以左侧抽屉打开，笔记则以整屏抽屉打开。把手机横过来，用的就是平板竖屏那套双栏布局。</p><h2 id="平板竖屏-—-820-×-1180" tabindex="-1">平板竖屏 — 820 × 1180 <a class="header-anchor" href="#平板竖屏-—-820-×-1180" aria-label="Permalink to &quot;平板竖屏 — 820 × 1180&quot;">​</a></h2><figure class="shot"><img src="'+e+'" alt="820 × 1180 的窗口：顶栏一行，对照栏纵向堆叠"><figcaption>820 × 1180：顶栏一行，侧栏收在抽屉里；鼠标窗口里对照纵向堆叠，触屏平板则两栏并排。</figcaption></figure><p>KomaYomi 的对照布局由指针类型和宽高比共同决定，不只看宽度。在 820 px 的鼠标窗口里，各语言栏纵向堆叠成一栏。触屏平板竖屏时，每个格子并排显示两条语言栏；启用超过两种语言时，舞台上方的语言标签栏负责切换当前显示的一对，从当前聚焦的语言开始。宽度不超过 900 px 的手机横屏也使用这套双栏布局。顶栏保持一行，侧栏仍是抽屉，工具栏会折行并把放不下的操作收进 <strong>More</strong>，笔记以抽屉形式盖在对照区上打开。</p><h2 id="平板横屏-—-1180-×-820" tabindex="-1">平板横屏 — 1180 × 820 <a class="header-anchor" href="#平板横屏-—-1180-×-820" aria-label="Permalink to &quot;平板横屏 — 1180 × 820&quot;">​</a></h2><figure class="shot"><img src="'+s+'" alt="1180 × 820 的平板窗口：侧栏展开，三语并排"><figcaption>1180 × 820：侧栏展开，三语并排，笔记仍是抽屉。</figcaption></figure><p>1180 px 时侧栏（240 px）重新出现，三语并排，每栏约 290 px。触屏平板横屏时，宽度不超过 900 px 用两栏，超过 900 px 到 1199 px 用三栏；启用的语言多于栏数时才会出现语言标签栏。这个宽度下笔记仍是抽屉，打开后盖在对照区上；工具栏保持两排——语言与对齐控制在上一排，标注工具在下一排，<strong>Export HTML</strong> 留在顶栏。</p><div class="info custom-block"><p class="custom-block-title">关于手机与平板竖屏截图</p><p>上面的 390 × 844 与 820 × 1180 截图是在鼠标操作的浏览器窗口里截的，所以呈现的是桌面端的堆叠规则。在触屏手机或平板上，KomaYomi 使用本页描述的触屏布局：手机一条语言栏，平板竖屏两条并排。</p></div><div class="tip custom-block"><p class="custom-block-title">自己想截图的话</p><p>请直接调整浏览器窗口大小，不要用页面缩放：断点跟的是视口宽度，侧栏和笔记栏只有窗口本身越过断点才会换位置。</p></div>',19)])])}const P=r(l,[["render",d]]);export{b as __pageData,P as default};
